use std::backtrace::{Backtrace, BacktraceStatus};
use std::error::Error;
use std::fmt::{Debug, Display, Formatter};
use std::fmt;

/// Implements `From<$error_type>` for `$target`. The target must implement
/// `From<$crate::AppError>` (which `AppError`, `AppErrorStatic`, and any
/// newtype generated by `define_app_error!` / `define_app_error_static!`
/// all do).
///
/// Used both inside minimer to register conversions from std error types
/// onto `AppError` / `AppErrorStatic`, and downstream to register
/// conversions onto a consumer's newtype.
#[macro_export]
macro_rules! impl_from_error {
    ($target:ty, $error_type:ty) => {
        impl ::std::convert::From<$error_type> for $target {
            fn from(value: $error_type) -> Self {
                <$target>::from($crate::AppError::from_error_default(::std::boxed::Box::new(value)))
            }
        }
    };
}

/// Generates a newtype wrapping `$crate::AppError` with all the trait forwards
/// (Display, Debug, Error, Deref, From<AppError>, From<String>, From<&str>)
/// and constructor methods (`new`, `from_error`) needed for the wrapper to
/// behave as an error type.
///
/// Use this when a downstream crate wants to register `From<X>` conversions
/// for foreign error types — Rust's orphan rule prevents downstream crates
/// from implementing `From<X> for $crate::AppError` directly, so the
/// downstream defines its own newtype and uses `impl_from_error!` against it.
///
/// Example:
/// ```ignore
/// minimer::define_app_error!(pub AppError);
/// minimer::impl_from_error!(AppError, sqlx::Error);
/// ```
#[macro_export]
macro_rules! define_app_error {
    ($vis:vis $name:ident) => {
        $vis struct $name(pub $crate::AppError);

        impl $name {
            pub fn new(message: &str) -> Self {
                Self($crate::AppError::new(message))
            }

            pub fn from_error(message: &str, error: ::std::boxed::Box<dyn ::std::error::Error>) -> Self {
                Self($crate::AppError::from_error(message, error))
            }
        }

        impl ::std::fmt::Display for $name {
            fn fmt(&self, formatter: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
                ::std::fmt::Display::fmt(&self.0, formatter)
            }
        }

        impl ::std::fmt::Debug for $name {
            fn fmt(&self, formatter: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
                ::std::fmt::Debug::fmt(&self.0, formatter)
            }
        }

        impl ::std::error::Error for $name {}

        impl ::std::ops::Deref for $name {
            type Target = $crate::AppError;
            fn deref(&self) -> &Self::Target { &self.0 }
        }

        impl ::std::convert::From<$crate::AppError> for $name {
            fn from(error: $crate::AppError) -> Self {
                Self(error)
            }
        }

        impl ::std::convert::From<::std::string::String> for $name {
            fn from(message: ::std::string::String) -> Self {
                Self($crate::AppError::from(message))
            }
        }

        impl ::std::convert::From<&str> for $name {
            fn from(message: &str) -> Self {
                Self($crate::AppError::from(message))
            }
        }

        $crate::impl_from_error!($name, ::std::io::Error);
        $crate::impl_from_error!($name, ::std::array::TryFromSliceError);
        $crate::impl_from_error!($name, ::std::num::TryFromIntError);
        $crate::impl_from_error!($name, ::std::string::FromUtf8Error);
        $crate::impl_from_error!($name, ::std::env::VarError);
        $crate::impl_from_error!($name, ::std::num::ParseIntError);
        $crate::impl_from_error!($name, ::std::num::ParseFloatError);
        $crate::impl_from_error!($name, ::std::str::Utf8Error);
    };
}

/// Generates a newtype wrapping `$crate::AppErrorStatic` (the dyn-compatible
/// variant) with all the trait forwards needed for the wrapper to behave as
/// an error type.
///
/// Use when a downstream crate needs a dyn-compatible error wrapper (e.g.,
/// for storage in trait objects). Most consumers want `define_app_error!`
/// instead.
#[macro_export]
macro_rules! define_app_error_static {
    ($vis:vis $name:ident) => {
        $vis struct $name(pub $crate::AppErrorStatic);

        impl $name {
            pub fn new(message: &str) -> Self {
                Self($crate::AppErrorStatic::new(message))
            }
        }

        impl ::std::fmt::Display for $name {
            fn fmt(&self, formatter: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
                ::std::fmt::Display::fmt(&self.0, formatter)
            }
        }

        impl ::std::fmt::Debug for $name {
            fn fmt(&self, formatter: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
                ::std::fmt::Debug::fmt(&self.0, formatter)
            }
        }

        impl ::std::error::Error for $name {}

        impl ::std::ops::Deref for $name {
            type Target = $crate::AppErrorStatic;
            fn deref(&self) -> &Self::Target { &self.0 }
        }

        impl ::std::convert::From<$crate::AppErrorStatic> for $name {
            fn from(error: $crate::AppErrorStatic) -> Self {
                Self(error)
            }
        }

        impl ::std::convert::From<$crate::AppError> for $name {
            fn from(error: $crate::AppError) -> Self {
                Self($crate::AppErrorStatic::from(error))
            }
        }

        impl ::std::convert::From<::std::string::String> for $name {
            fn from(message: ::std::string::String) -> Self {
                Self($crate::AppErrorStatic::from(message))
            }
        }

        impl ::std::convert::From<&str> for $name {
            fn from(message: &str) -> Self {
                Self($crate::AppErrorStatic::from(message))
            }
        }

        $crate::impl_from_error!($name, ::std::io::Error);
        $crate::impl_from_error!($name, ::std::array::TryFromSliceError);
        $crate::impl_from_error!($name, ::std::num::TryFromIntError);
        $crate::impl_from_error!($name, ::std::string::FromUtf8Error);
        $crate::impl_from_error!($name, ::std::env::VarError);
        $crate::impl_from_error!($name, ::std::num::ParseIntError);
        $crate::impl_from_error!($name, ::std::num::ParseFloatError);
        $crate::impl_from_error!($name, ::std::str::Utf8Error);
    };
}

/// Should be initialized lazily (e.g. [Option::ok_or_else]) for captured backtraces to make sense.
pub struct AppError {
    pub message: String,
    pub sub_error: Option<Box<dyn Error>>,
    pub backtrace: Backtrace,
}

impl Error for AppError {}

impl Default for AppError {
    fn default() -> Self {
        Self::new(Self::DEFAULT_MESSAGE)
    }
}

impl Debug for AppError {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        Display::fmt(self, f)
    }
}

impl Display for AppError {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        write!(f, "AppError [{}]", self.message)?;
        if let Some(sub_error) = &self.sub_error {
            write!(f, "\n[{}]", sub_error)?;
        }
        match self.backtrace.status() {
            BacktraceStatus::Unsupported | BacktraceStatus::Disabled => Ok(()),
            BacktraceStatus::Captured => write!(f, "\n{}", self.backtrace),
            _ => Ok(()),
        }
    }
}

impl From<AppErrorStatic> for AppError {
    fn from(value: AppErrorStatic) -> Self {
        AppError {
            message: value.message,
            sub_error: None,
            backtrace: value.backtrace,
        }
    }
}

impl From<String> for AppError {
    fn from(message: String) -> Self {
        Self::new(&message)
    }
}

impl From<&str> for AppError {
    fn from(message: &str) -> Self {
        Self::new(message)
    }
}

impl AppError {
    const DEFAULT_MESSAGE: &'static str = "unspecified";

    pub fn new(message: &str) -> AppError {
        Self::_new(message, None)
    }

    pub fn from_error(message: &str, error: Box<dyn Error>) -> AppError {
        Self::_new(message, Some(error))
    }

    pub fn from_error_default(error: Box<dyn Error>) -> AppError {
        Self::_new(&error.to_string(), Some(error))
    }

    fn _new(message: &str, error: Option<Box<dyn Error>>) -> AppError {
        let backtrace: Backtrace = Backtrace::force_capture();
        AppError {
            message: format!("Error: {}", message),
            sub_error: error,
            backtrace,
        }
    }
}

/// Like [AppError], but cannot include a sub error (in order to be dyn-compatible).
/// Should be initialized lazily (e.g. [Option::ok_or_else]) for captured backtraces to make sense.
pub struct AppErrorStatic {
    pub message: String,
    pub backtrace: Backtrace,
}

impl Error for AppErrorStatic {}

impl Default for AppErrorStatic {
    fn default() -> Self {
        Self::new(Self::DEFAULT_MESSAGE)
    }
}

impl Display for AppErrorStatic {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        write!(f, "AppError [{}]", self.message)?;
        match self.backtrace.status() {
            BacktraceStatus::Unsupported | BacktraceStatus::Disabled => Ok(()),
            BacktraceStatus::Captured => write!(f, "\n{}", self.backtrace),
            _ => Ok(()),
        }
    }
}

impl Debug for AppErrorStatic {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        Display::fmt(self, f)
    }
}

/// The sub error cannot cross into [AppErrorStatic], so its chain of sources is kept as text in the message.
impl From<AppError> for AppErrorStatic {
    fn from(value: AppError) -> Self {
        let message: String = match value.sub_error {
            Some(sub_error) => format!("{} -> {}", value.message, render_source_chain(sub_error.as_ref())),
            None => value.message,
        };

        AppErrorStatic {
            message,
            backtrace: value.backtrace,
        }
    }
}

/// `error` followed by each of its sources, separated by ` -> `.
fn render_source_chain(error: &dyn Error) -> String {
    let mut rendered: String = error.to_string();
    let mut next: Option<&dyn Error> = error.source();

    while let Some(source) = next {
        rendered.push_str(" -> ");
        rendered.push_str(&source.to_string());
        next = source.source();
    }

    rendered
}

impl From<String> for AppErrorStatic {
    fn from(message: String) -> Self {
        Self::new(&message)
    }
}

impl From<&str> for AppErrorStatic {
    fn from(message: &str) -> Self {
        Self::new(message)
    }
}

impl AppErrorStatic {
    const DEFAULT_MESSAGE: &'static str = "unspecified";

    pub fn new(message: &str) -> AppErrorStatic {
        let backtrace: Backtrace = Backtrace::force_capture();
        AppErrorStatic {
            message: format!("Error: {}", message),
            backtrace,
        }
    }
}
